A1=['01100','00000','11100','10000','10101','00100']; B1=['00101','00000','00110','00010','01011','00001']
A2=['10101','00001','10111','01110','00101','10100']; B2=['00111','00010','01111','11001','00011','00101']
for convention in [1,0]:
 for boundary in ['dead','wrap']:
  for birth in range(9):
   for surv in range(9):
    good=True
    for A,B in [(A1,B1),(A2,B2)]:
     h,w=len(A),len(A[0]); out=[]
     for r in range(h):
      row=''
      for c in range(w):
       v=int(A[r][c]) if convention else 1-int(A[r][c]); n=0
       for dr in [-1,0,1]:
        for dc in [-1,0,1]:
         if dr==dc==0:continue
         rr,cc=r+dr,c+dc
         if boundary=='wrap': rr%=h;cc%=w
         if 0<=rr<h and 0<=cc<w:n+=int(A[rr][cc]) if convention else 1-int(A[rr][cc])
       nv=(n==surv if v else n==birth)
       ov=nv if convention else not nv
       row+=str(int(ov))
      out.append(row)
     if out!=B:good=False
    if good:print('match',convention,boundary,birth,surv)
